    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function parse_file_path_root(
             $application_directory, 
             $R_framework_directory = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added parse_file_path_root() method 
         *       to the crnrstn class object. 
         *       This will replace the use of 
         *       return_boot_resource_path() that was
         *       added on March 9, 2026.
         *       5 :: Tuesday, March 31, 2026 @ 2302 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, parse_file_path_root(), 
         * to crnrstn_registry_user from crnrstn.
         * 5 :: Tuesday, May 26, 2026 @ 2029 hrs.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Variable Initialization.
         *
         */
        $tmp_path_root = NULL;
        $tmp_crnrstn_file_path = NULL;

        if(!isset($application_directory)){

            $application_directory = self::$R_data['application_directory'];

        }

        if(isset($R_framework_directory)){

            self::$R_data['framework_directory'] = $R_framework_directory;

        }else{

            self::$R_data['framework_directory'] = $this->R_load_static('framework_directory');

        }

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Evaluate $application_directory for 
         * any change directory input commands. 
         *
         * Happy birthday to you, J5, my boy! 
         * 11/11/2005 - 08/16/2021 @ 0345 hrs. 
         *
         *
         * 5 :: Tuesday, November 11, 2025 @ 2111 hrs.
         *
         */
        if((strpos($application_directory, '../') !== false) || 
            ($application_directory == ''))
        {

            $tmp_data = explode('../', $application_directory);
            $tmp_change_directory_depth = sizeof($tmp_data);
            $tmp_script_filepath_ARRAY = explode(\DIRECTORY_SEPARATOR, $_SERVER['SCRIPT_FILENAME']);

            for($i = 0; $i < $tmp_change_directory_depth; $i++){

                $tmp_data = array_pop($tmp_script_filepath_ARRAY);

            }

            $tmp_path_root = implode(\DIRECTORY_SEPARATOR, $tmp_script_filepath_ARRAY) . \DIRECTORY_SEPARATOR;

        }

        if(!isset($tmp_path_root))
        {

            $tmp_path_root = $_SERVER['DOCUMENT_ROOT'];

            if($application_directory != '') $tmp_path_root .= \DIRECTORY_SEPARATOR . 
                                                               $application_directory;

        }

        return $tmp_path_root . \DIRECTORY_SEPARATOR . 
               self::$R_data['framework_directory'];

    }

