    function error_log_clear($message_token = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * 5 :: Tuesday, May 12, 2026 @ 0845 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, 
         * error_log_clear(), 
         * to crnrstn_registry_user 
         * from crnrstn. 
         * 5 :: Tuesday, May 26, 2026 @ 2026 hrs.
         *
         */

        if(isset(self::$R_logging)){
            // 5 :: Friday, May 22, 2026 @ 1107 hrs.

            return self::$R_logging->error_log_clear($message_token);

        }

        if(isset($message_token)){

            if(isset(self::$R_data['spool']['err_message_queue_push'][$message_token])){

                //array_splice(self::$R_data['spool']['err_message_queue_push']['message_token'], 0); // Clear all tokens?
                array_splice(self::$R_data['spool']['err_message_queue_push'][$message_token]['message'], 0);
                array_splice(self::$R_data['spool']['err_message_queue_push'][$message_token]['data_authorization_profile'], 0);

            }

        }

        if(isset(self::$R_data['R_cluster_id'])){

            if(isset($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'])){

                array_splice($_SESSION['CRNRSTN_ERROR_PREFIX_' . 
                    self::$R_data['R_cluster_id']]['CRNRSTN_EXCEPTION_PREFIX']['SYSTEM_ID'], 
                    0);

            }

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function clr_ssl_syslog_prefix(
             $line_num, 
             $file, 
             $method = '', 
             $prefix_override = NULL,
             $syslog_prefix_passthrough = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, 
         * clr_ssl_syslog_prefix(), 
         * to crnrstn_registry_user 
         * from crnrstn. 
         * 5 :: Tuesday, May 26, 2026 @ 2025 hrs.
         *
         */

        if(isset(self::$R_logging)){
            // 5 :: Friday, May 22, 2026 @ 1109 hrs.

            return self::$R_logging->clr_ssl_syslog_prefix(
                                     $line_num, 
                                     $file, 
                                     $method, 
                                     $prefix_override,
                                     $syslog_prefix_passthrough);

        }

        if(\strlen(\trim($syslog_prefix_passthrough)) < 1){

            $syslog_prefix = 'R :: ';
            if(isset($prefix_override)){

                $syslog_prefix = $prefix_override;

            }

            $syslog_prefix .= '[' . $this->return_micro_time() . 
                              '] ';

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * String concat __METHOD__ 
             * only if data exists. 
             *
             *
             * 5 :: Wednesday, May 20, 2026 @ 1540 hrs.
             *
             */
            if($method != ''){

                $syslog_prefix .= '[mthd ' . 
                                  $method . '] ';

            }else{

                if($file != ''){

                    $syslog_prefix .= '[file ' . 
                                      $file . '] ';

                }

            }

            $syslog_prefix .= '[lnum ' . 
                              $line_num . '] [rtime ' . 
                              $this->wall_time() . 
                              '] ';

        }else{

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Apply a syslog prefix 
             * white labeling overwrite. 
             *
             *
             * 5 :: Friday, May 22, 2026 @ 0655 hrs.
             *
             */
            $syslog_prefix = $syslog_prefix_passthrough;

        }

        return $syslog_prefix;

    }

    /**
     * R :: Content pending. 
