     *
     */
    function session_runtime(
             $reporting_mode = CRNRSTN_FLOAT, 
             $finite_express_mode = 'ELAPSED', 
             $decimal = 8)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, session_runtime(), 
         * to crnrstn_registry_user from crnrstn. 
         * 5 :: Tuesday, May 26, 2026 @ 2024 hrs.
         *
         */

        if(isset(self::$R_session_mgr)){
            // 5 :: Wednesday, June 10, 2026 @ 0055 hrs.

            return self::$R_session_mgr->session_runtime(
                                         $reporting_mode, 
                                         $finite_express_mode, 
                                         $decimal);

        }

        if(!isset($_SESSION['R_cluster_id_starttime'])){

            $_SESSION['R_cluster_id_starttime'] = $this->microtime_float();

        }

        $tmp_mirco_time_float = $this->microtime_float();

        $timediff = $tmp_mirco_time_float - $_SESSION['R_cluster_id_starttime'];

        $len = $decimal * -1;

        switch($reporting_mode){
            case CRNRSTN_STRING:

                if(isset(self::$R_finite_expression)){
                    // 5 :: Wednesday, June 10, 2026 @ 0100 hrs.

                   return self::$R_finite_expression->incarnate(
                                                      $finite_express_mode, 
                                                      $timediff, 
                                                      true);

                }

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * For now, just return the secs. 
                 *
                 * We are working on file system 
                 * automation (and finishing that 
                 * crnrstn_ascii_art class) with the 
                 * R_finite_expression instantiation 
                 * exe being missing and needing a 
                 * file write in the middle of a 
                 * CLR-SSL Resource Registry 
                 * operation. 
                 *
                 * We will change the wheels out 
                 * while the car is going dow the 
                 * highway in the fast lane. 
                 *
                 * ...the CRNRSTN :: PLAID fast lane. 
                 *
                 *
                 * 5 :: Wednesday, June 10, 2026 @ 0107 hrs.
                 * sips SweetWater® 420 beer in a can.
                 *
                 */
                return $len;

            break;
            case CRNRSTN_FLOAT:
            case CRNRSTN_DOUBLE:

                if(self::$R_data['operating_system']['name'] == 'Windows®'){

                    return (double) $timediff;

                }

                return substr($timediff, 0, $len);

            break;
            case CRNRSTN_INT:
            case CRNRSTN_INTEGER:
            default:

                if(self::$R_data['operating_system']['name'] == 'Windows®'){

                    return (int) $timediff;

                }

                return substr($timediff, 0, $len);

            break;

        }

    }

