         *       $syslog_constant input parameter 
         *       to $syslog_level.
         *       5 :: Friday, May 1, 2026 @ 0052 hrs.
         *
         */

        $tmp_err_trace_str = $this->return_PHP_exception_trace_pretty($exception_obj->getTraceAsString());

        if(\strlen($tmp_err_trace_str) > 0){

            $this->error_log('PHP native exception ' .
            'output log trace received ::' .
            $tmp_err_trace_str, __LINE__, __METHOD__, __FILE__, CRNRSTN_SETTINGS_CRNRSTN);

        }

        /*
        # syslog()
        # SYSLOG priority is a combination of
        # the facility and the level.
        #
        # Possible values are (in
        # descending order):
        # -----
        # Constant      Description
        # LOG_EMERG     system is unusable.
        # LOG_ALERT     action must be taken immediately
        # LOG_CRIT      critical conditions
        # LOG_ERR       error conditions
        # LOG_WARNING   warning conditions
        # LOG_NOTICE    normal, but significant, condition
        # LOG_INFO      informational message
        # LOG_DEBUG     debug-level message

        Exception $e
        final public getMessage ( void ) : string
        final public getPrevious ( void ) : Throwable
        final public getCode ( void ) : mixed
        final public getFile ( void ) : string
        final public getLine ( void ) : int
        final public getTrace ( void ) : array
        final public getTraceAsString ( void ) : string
        public __toString ( void ) : string
        final private __clone ( void ) : void

        $this->error_log('121 - getMessage=' . $exception_obj->getMessage());
        $this->error_log('122 - getPrevious=' . $exception_obj->getPrevious());
        $this->error_log('123 - getCode=' . $exception_obj->getCode());
        $this->error_log('124 - getFile=' . $exception_obj->getFile());
        $this->error_log('125 - getLine=' . $exception_obj->getLine());
        $this->error_log('126 - getTraceAsString=' . $exception_obj->getTraceAsString());

        121 - getMessage=The requested _SERVER super global parameter [CLOWN_TOWN] cannot be found.
        122 - getPrevious=
        123 - getCode=0
        124 - getFile=/var/www/html/crnrstn_v2/_lightbox_helper/class/environment/crnrstn.environment.inc.php
        125 - getLine=403
        126 - getTraceAsString=#0 /var/www/html/crnrstn_v2/_lightbox_helper/class/user/crnrstn.user.inc.php(6063): crnrstn_environment->getServerArrayVar('CLOWN_TOWN', Object(crnrstn_user))\n#1 /var/www/html/crnrstn_v2/common/inc/footer/footer.inc.php(591): crnrstn_user->get_SERVER_param('CLOWN_TOWN')\n#2 /var/www/html/crnrstn_v2/index.php(132): include_once('/var/www/html/c..')\n#3 {main}

        */

        $tmp_exception_msg        = $exception_obj->getMessage();
        $tmp_exception_linenum    = $exception_obj->getLine();
        $tmp_exception_runtime    = $this->wall_time();
        $tmp_exception_systemtime = $this->return_micro_time();

        $exception_method_trim    = $method;
        if(isset($method)){

            $exception_method_trim = trim($method);

        }

        if(isset($exception_method_trim)){

            if($exception_method_trim == ''){

                $tmp_source_method = '';
                $tmp_exception_method = $exception_obj->getFile();
                $method = 'file';

            }else{

                $tmp_source_method = $exception_method_trim;
                $tmp_exception_method = $exception_method_trim . '()';
                $method = 'methd';

            }

        }else{

            $tmp_source_method = '';
            $tmp_exception_method = $exception_obj->getFile();
            $method = 'file';

        }

        //error_log('[rtime ' . $tmp_exception_runtime . ' secs] [' . $method . ' ' . $tmp_exception_method . '] [lnum ' . $tmp_exception_linenum . '] ' . $tmp_exception_msg);
        $tmp_exception_output_str = $tmp_exception_systemtime . ' [rtime ' .
            $tmp_exception_runtime . ' secs] [' . $method . ' ' .
            $tmp_exception_method . '] [lnum ' .
            $tmp_exception_linenum . '] ' . $tmp_exception_msg;

        error_log($tmp_exception_output_str);

    }

