    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function convert_str_to_resource_registry_name($data)
    {

        $tmp_registry_name = array();
        $tmp_data_str = $data;

        if(is_array($data)){

            //
            // Convert all array
            // data to string data
            // for the purposes of
            // request standardization.
            //
            //
            // 5
            //
            // Sunday, August 11, 2024 @ 0601 hrs.
            //$tmp_data_str = $this->convert_boot_resource_to_concatenated_str($data);
            //
            //
            // Converting this $data to
            // string using,
            //
            // convert_boot_resource_to_concatenated_str(),
            //
            // will strip out
            // registry name meta such
            // as 'CLASS_DEFINITION'
            // and 'FUNCTION_DEFINITION'.
            //
            // We will just kick back
            // any array input data
            // for now.
            //
            // Sunday, August 11, 2024 @ 0606 hrs.
            return $data;

        }

        //
        // Remove all spaces.
        $tmp_data_str = $this->str_sanitize($tmp_data_str, 'remove_all_spaces');

        $tmp_pos_comma = strpos($tmp_data_str, ',');
        $tmp_pos_pipe = strpos($tmp_data_str, '|');

        if($tmp_pos_comma !== false){

            //
            // Produce an array
            // broken down from
            // the midst of
            // a comma delimited
            // string of registered
            // resource names that
            // are requesting to
            // be loaded by the
            // CRNRSTN :: Lightsaber
            // SOAP Services Layer
            // native system registry.
            //
            //
            // 5
            //
            // Sunday, August 11, 2024 @ 0552 hrs.
            $tmp_registry_name = explode(',', $tmp_data_str);

        }else{

            if($tmp_pos_pipe !== false){

                //
                // Produce an array
                // broken down from
                // the midst of
                // a pipe delimited
                // string of registered
                // resource names that
                // are requesting to
                // be loaded by the
                // CRNRSTN :: Lightsaber
                // SOAP Services Layer
                // native system registry.
                //
                //
                // 5
                //
                // Sunday, August 11, 2024 @ 0552 hrs.
                $tmp_registry_name = explode('|', $tmp_data_str);

            }

        }

        //
        // Return the standardized
        // CRNRSTN :: Lightsaber
        // SOAP Services Layer
        // system resource
        // registry name data.
        //
        //
        // 5
        //
        // Sunday, August 11, 2024 @ 0611 hrs.
        return $tmp_registry_name;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function convert_boot_resource_to_concatenated_str($data)
    {
        // 5 :: Wednesday, July 24, 2024 @ 2111 hrs.

        $tmp_res_str = '';
        $tmp_str_concat_char = $this->get_data('string_concat_delimiter_char');

        $tmp_is_resource_flag_data = $this->is_resource_flag_data_array($data);

        //
        // Convert the array data
        // to string data so that
        // the data can line up
        // for flush processing
        // like how all the
        // other kids do it.
        //
        //
        // 5
        //
        // Wednesday, July 24, 2024 @ 2043 hrs.
        foreach($data as $res_maybe => $flag_maybe){

            if($tmp_is_resource_flag_data !== false){

                //
                // We have array data
                // that looks like:
                //
                // 'registry_name' => flag
                $res = $res_maybe;

            }else{


                //
                // We have array data
                // that looks like:
                //
                // index => 'registry_name'
                $res = $flag_maybe;

            }

            //
            // Build concatenated
            // string of resource
            // names to flush the
            // boot resources to
            // runtime memory.
            //
            //
            // 5 :: Wednesday, July 24, 2024 @ 1851 hrs.
            $tmp_res_str .= $res . $tmp_str_concat_char;

        }

        //
        // Remove the trailing
        // delimiting character
        // from the CRNRSTN ::
        // Lightsaber SOAP
        // Services Layer
        // concatenated string
        // of system
        // registered resources.
        //
        //
        // Please note,
        // convert_boot_resource_to_concatenated_str()
        // will convert any
        // array into a
        // concatenated string
        // according to its
        // own data.
        //
        // Then only the
        // trailing concatenation
        // character, or the
        // delimiter, will be
        // removed and the
        // string data returned.
        //
        //
        // 5
        //
        // Wednesday, July, 24, 2024 @ 2122 hrs.
        $tmp_res_str = $this->strrtrim($tmp_res_str, $tmp_str_concat_char);

        return $tmp_res_str;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function is_resource_flag_data_array($data)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method was copied 
         * from The Lightbox Helper 
         * by eVifweb® 
         * 5 :: Thursday, August 8, 2024 @ 0127 hrs.
         *
         */

        foreach($data as $res => $flag){

            // Is the flag not
            // a clean integer flag?
            if(!is_int($flag)){

                //
                // Maybe the flag
                // is dirty.
                //
                // Is the data
                // even numeric?
                if(is_numeric($flag)){

                    //
                    // Ok.
                    //
                    // We have flag
                    // data, but it
                    // is just a
                    // dirty string
                    // or something.
                    $flag = (int) $flag * 1;

                    //
                    // We have array data
                    // that looks like:
                    //
                    // 'registry_name' => (int) flag
                    //
                    // Now the flag
                    // is dutty!
                    return true;

                }else{

                    //
                    // The flag data
                    // is not numeric.
                    //
                    // We will skip
                    // any $res checks
                    // to see if it is
                    // an index.
                    //
                    // Hopefully, $res
                    // is an index.
                    //
                    // Hopefully, we
                    // have array data
                    // that looks like:
                    //
                    // (int) index => 'registry_name'
                    //
                    //
                    // 5
                    //
                    // Wednesday, July 24, 2024 @ 2102 hrs.
                    return false;

                }

            }else{

                //
                // We have array data
                // that looks like:
                //
                // 'registry_name' => (int) flag
                //
                // The flag was
                // borne dutty!
                //
                //
                // 5
                //
                // Wednesday, July 24, 2024 @ 2104 hrs.
                return true;

            }

            //
            // Build concatenated
            // string of resource
            // names to flush the
            // boot resources to
            // runtime memory.
            //
            //
            // 5 :: Wednesday, July 24, 2024 @ 1851 hrs.
            $tmp_res_str .= $res . $tmp_str_concat_char;

        }

    }

