        switch($R_action){
            case 'dependency_ping':
                // 5 :: Saturday, April 25, 2026 @ 0223 hrs.

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Minimum token length = 64 bytes. 
                 * Maximum token length = 275 bytes. 
