    //
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function strrtrim(
             $message, 
             $strip)
    {

        //
        // Break message
        // apart by
        // strip string.
        $lines = explode($strip, $message);
        $last = '';

        //
        // Pop off empty
        // strings at
        // the end.
        //
        //
        // 5
        do{

            $last = array_pop($lines);

        }while(empty($last) && (count($lines)));

        //
        // Re-assemble
        // what remains.
        //
        //
        // 5
        return implode($strip, array_merge($lines, array($last)));

    }

