                                // authorizing the selections of
                                // TB (Terabyte), EB (Exabyte),
                                // and YB (Yottabyte)
                                // exponentials due to
                                // potential string
                                // algorithm collisions with
                                // basic bitch byte detection.
                                foreach(self::$R_data['R_byte_units']['ISO_80000']['string_pattern']['units_bytes_positive'] as 
                                    $unit_pattern_iso => $control_index_int)
                                {

                                    $tmp_iso_short_pos = strpos($tmp_bytes_human_str_to_lower, $unit_pattern_iso);

                                    if($tmp_iso_short_pos !== false){

                                        //
                                        // Extract the number.
                                        $tmp_str_explode_ARRAY = explode($unit_pattern_iso, $tmp_bytes_human_str_to_lower);
                                        $tmp_number = $tmp_str_explode_ARRAY[0];

                                        //$tmp_detection_track_breadcrumb_ARRAY[] = '<br>' . __LINE__ . ' ISO STRING [BYTES POSITIVE] MATCH ON: ' . $unit_pattern_iso . '. ';

                                        //
                                        // A final double,
                                        // triple check.
                                        //
                                        // Check for literal
                                        // positive matches on
                                        // TB (Terabyte),
                                        // EB (Exabyte),
                                        // and YB (Yottabyte).
                                        foreach(self::$R_data['R_byte_units']['SI_Metric']['string_pattern']['units_exponential_positive'] as 
                                            $unit_pattern_si => $control_index_si_int)
                                        {

                                            $tmp_si_short_pos = \strpos($tmp_bytes_human_str_to_lower, $unit_pattern_si);
                                            if($tmp_si_short_pos !== false){

                                                //
