                                                $tmp_unit_system = 'SI_Metric';
                                                $tmp_unit_index = $control_index_si_int;

                                                break 2;

                                            }

                                        }

                                        //
                                        // There was a positive full string
                                        // match on "bytes".
                                        //
                                        // Before honoring this, and in order
                                        // to have less chance of illness...and
                                        // shoring up against future lamentation,
                                        // we needed to check (above) first for
                                        // string collisions with other full
                                        // string ISO/IEC 80000 and SI
                                        // metric units.
                                        //
                                        // At this point, go ahead and just
                                        // force bytes.
                                        //
                                        // Then eject.
                                        $tmp_input_byte_unit_matched = self::$R_data['R_byte_units']['ISO_80000']['string_pattern']['units_bytes_positive'][$unit_pattern_iso];
                                        //$tmp_detection_track_breadcrumb_ARRAY[] = '<br>' . __LINE__ . ' ISO BYTES POSITIVE ON: ' . $unit_pattern_iso;

                                        $tmp_unit_system = 'ISO_80000';
                                        $tmp_unit_index = $control_index_int;

                                        break 2;

                                    }

                                }

                            }

                            if(!isset($tmp_unit_system)){

                                //
                                // Extract the number.
                                $tmp_str_explode_ARRAY = explode($unit_pattern, $tmp_bytes_human_str_to_lower);
                                $tmp_number = $tmp_str_explode_ARRAY[0];

                                $tmp_unit_system = 'SI_Metric';
                                $tmp_unit_index = self::$R_data['R_byte_units']['SI_Metric']['control_pattern'][$unit_pattern];

                            }

                        }

