                    }

                }

            }

            if(!isset($tmp_input_byte_unit_matched)){

                //
                // If no match yet,
                // check for basic
                // bitch bytes...as
                // string input...?
                //
                // Dude!?! I hope that
                // this is grunt work
                // input from another
                // computer system
                // (e.g. UGC from
                // CRNRSTN :: Messenger
                // UI Interact user-
                // to-bot basic
                // banter/chit-chat.
                //
                // "500000000000 bytes
                // to tb, slave"
                //
                // ...[then presses
                //     enter to
                //     send message]
                foreach(self::$R_data['R_byte_units']['ISO_80000']['string_pattern']['ISO_units_bytes'] as 
                    $unit_pattern_iso => $unit_word_iso)
                {

                    $tmp_iso_short_pos = strpos($tmp_bytes_human_str_to_lower, $unit_pattern_iso);
                    if($tmp_iso_short_pos !== false){

                        //
                        // Extract the
                        // number.
                        $tmp_str_explode_ARRAY = explode($unit_pattern_iso, $tmp_bytes_human_str_to_lower);
                        $tmp_number = $tmp_str_explode_ARRAY[0];

                        //
                        // self::$byte_units_ARRAY['ISO_80000']['control_pattern'][$unit_pattern] FOR BYTES IS 0;
                        $tmp_input_byte_unit_matched = self::$R_data['R_byte_units']['ISO_80000']['control_pattern'][$unit_pattern_iso];
