                        $tmp_unit_system = 'ISO_80000';
                        $tmp_unit_index = self::$R_data['R_byte_units']['ISO_80000']['control_pattern'][$unit_pattern_iso];

                        break 1;

                    }

                }

            }

            if(!isset($tmp_input_byte_unit_matched)){

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * HOOOSTON, VE HAFF PROBLEM!
                 * https://www.wired.com/2011/04/alt-text-spacecraft/
                 *
                 */
                //throw new \Exception('Unable to determine ');
                $this->error_log('The system is unable to convert the ' .
                strtoupper(gettype($bytes)) . ' input data, ' .
                $bytes . ', to integer bytes.', __LINE__, __METHOD__, __FILE__, CRNRSTN_SETTINGS_CRNRSTN);

                return '';

            }

            //
            // Bytes (0) will assume
            // the system of units
            // as indicated by CRNRSTN ::
            // Lightsaber SOAP Services
            // configuration settings.
            if($tmp_unit_index == 0){

                $tmp_unit_system = self::$byte_reporting_system;

