    private function initialize_cpu_profile()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method was copied
         * from The Lightbox Helper
         * by eVifweb® 
         * 5 :: Wednesday, August 7, 2024 @ 2354 hrs.
         *
         */

        //
        // 5 :: Friday, October 24, 2025 @ 0533 hrs.
        switch(PHP_INT_SIZE){
            case 4:

                self::$R_data['os_bit_size'] = (int) 32;

            break;
            case 8:
            default:

                self::$R_data['os_bit_size'] = (int) 64;

            break;

        }

        return true;

        if(substr(PHP_OS, 0, 3) == 'WIN'){

            // Sorry, I do not
            // have Windows
            // commands yet.
            //
            // exec('for %I in ("' . $file . '") do @echo %~zI', $output);
            // $return = $output[0];
            self::$R_data['os_bit_size'] = (int) 64;

        }else{

            self::$lscpu_output = shell_exec('lscpu');
            self::$uname_output = shell_exec('uname -m');
            self::$getconf_output = (int) shell_exec('getconf LONG_BIT');
            //$this->getconf_output = 128;

            if(is_numeric(self::$getconf_output)){

                self::$R_data['os_bit_size'] = (int) self::$getconf_output;

            }else{

                $pos_32 = strpos(self::$uname_output, '32');

                if($pos_32 !== false){

                    self::$R_data['os_bit_size'] = (int) 32;

                }else{

                    //
                    // If we cannot
                    // detect 32,
                    // set to 64.
                    self::$R_data['os_bit_size'] = (int) 64;

                }

            }

        }

    }

