    function start_time()
    {

        return date("Y-m-d H:i:s", self::$R_data['starttime']);

    }

    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function wall_time()
    {

        $timediff = $this->microtime_float() - self::$R_data['starttime'];

        return substr($timediff, 0, -8);

    }

    /**
     * R :: Returns the time in seconds with microseconds.
     * 
     * SOURCE :: NuSOAP.PHP - http://sourceforge.net/projects/nusoap/
     *
     * @return string The time in seconds
     *                with microseconds
     * @access public
     *
     */
    function microtime_float()
    {

        //list($usec, $sec) = explode(' ', microtime());
        //return ((float)$usec + (float)$sec);

        if(function_exists(__NAMESPACE__ . '\gettimeofday')){

            $tod = gettimeofday();
            $sec = $tod['sec'];
            $usec = $tod['usec'];

        }else{

            $sec = time();
            $usec = 0;

        }

        return $sec . '.' . sprintf('%06d', $usec);

    }

    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
     * SOURCE :: NuSOAP.PHP - http://sourceforge.net/projects/nusoap/
     *
     * Returns the time 
     * in ODBC canonical 
     * form with microseconds. 
     *
     * @return string The time in 
     *                ODBC canonical 
     *                form with microseconds,  
     *                e.g., '2024-07-15 00:56:13.653016'.
     * @access public
     * 
     * This method ws copied 
     * from NuSOAP.PHP
     *
     */
    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function return_micro_time()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: The crnrstn_registry_user method, 
         *       getmicrotime(), was renamed to 
         *       return_micro_time() and the 
         *       duplicate return_micro_time() 
         *       method was deleted. 
         *       5 :: Tuesday, April 7, 2026 @ 1054 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Changed crnrstn_registry_user 
         *       return_micro_time method 
         *       visibility from private 
         *       to public. 
         *       5 :: Sunday, June 14, 2026 @ 1050 hrs.
         *
         */

        if(function_exists(__NAMESPACE__ . '\gettimeofday')){

            $tod = gettimeofday();
            $sec = $tod['sec'];
            $usec = $tod['usec'];

        }else{

            $sec = time();
            $usec = 0;

        }

        return strftime('%Y-%m-%d %H:%M:%S', $sec) . '.' . sprintf('%06d', $usec);

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function initialization_series_data_reporting_bytes($data)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Here in the crnrstn_registry_user, 
         * we kick off the CLR-SSL 
         * Initialization Series of 
         * class methods in order to
         * purify the lower level 
         * methods by removing to 
         * an "initialization_series_" 
         * prefixed method call, the 
         * code that uses raw brute 
         * force in order to manually 
         * perform work due to a 
         * lack of initialization as 
         * the framework is just 
         * getting started. 
         *
         *
         * 5 :: Wednesday, June 24, 2026 @ 0042 hrs.
         *       
         */

        $bytes = 0;

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Fall back onto PHP native, 
         * as the CLR-SSL framework is 
         * not yet ready. 
         *
         *
         * 5 :: Tuesday, April 21, 2026 @ 1346 hrs. 
         *
         */
        switch(\gettype($data)){
            case 'string':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://stackoverflow.com/questions/7568949/measure-string-size-in-bytes-in-php
                 * COMMENT :: https://stackoverflow.com/a/25299281
                 * AUTHOR :: Ulver :: https://stackoverflow.com/users/1773335/ulver
                 *
                 * Further to PhoneixS answer to get 
                 * the correct length of string in 
                 * bytes - Since mb_strlen()
                 * is slower than strlen(), for the 
                 * best performance one can check 
                 * "mbstring.func_overload" ini
                 * setting so that mb_strlen() is 
                 * used only when it is 
                 * really required:
                 *
                 * Thankfully, this check is no 
                 * longer needed as of PHP 8.0.0. 
                 * The function overloading
                 * "feature" has been removed as 
                 * of PHP 8.0.0, and deprecated 
                 * in 7.2.0.
                 *
                 *
                 * - Buttle Butkus, 2022, https://stackoverflow.com/a/7568984
                 *
                 * CRNRSTN :: PHP support.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case 'int':
            case 'integer':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: PHP SUPPORT.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case 'bool':
            case 'boolean':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://dev.to/shevchenkonik/memory-size-of-javascript-boolean-3mlj
                 *        Posted on Feb 20, 2020
                 *        [Originally published at shevchenkonik.com]
                 * AUTHOR :: Nik Shevchenko
                 *
                 * A boolean is actually 1 
                 * byte. But alignment may cause 
                 * 4 bytes to be used on a 
                 * 32-bit platform or 8 bytes on 
                 * a 64-bit platform. This old 
                 * trick comes from the 
                 * observation that allocated 
                 * memory takes up at least 4 
                 * or 8 bytes, and are aligned 
                 * in the way that the least 
                 * significant bit or three 
                 * will be zero. 
                 *
                 * In C++, the size of the type 
                 * boolean is implementation-
                 * defined and is usually equal 
                 * to 1 (the size of the type char, 
                 * and the smallest size a 
                 * type can have), but is not 
                 * required to be in 
                 * particular, in Visual Studio 
                 * up to version 4.2, it was 4. 
                 * More information about 
                 * C++ boolean values is 
                 * available at docs. 
                 * 
                 */

                switch(self::$R_data['os_bit_size']){
                    case 32:

                        $bytes = 4;

                    break;
                    case 64:

                        $bytes = 8;

                    break;
                    default:

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         */
                        $clr_ssl_msg = 'Unknown operating ' . 
                                       'system bit size. 8 bytes will ' . 
                                       'be assigned for BOOLEAN data; ' . 
                                       'on 64-bit platforms, CRNRSTN :: ' . 
                                       'reports BOOLEAN data as ' . 
                                       '8 bytes.';
                        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token = array(
                                 'token'                   => $msg_token, 
                                 'token_generation_date'   => $token_generation_date, 
                                 'request_type'            => __METHOD__, 
                                 'code'                    => 200, 
                                 'clr_ssl_msg'             => $clr_ssl_msg);
                        $this->error_log(
                               $clr_ssl_msg, 
                               \LOG_NOTICE, 
                               \E_NOTICE, 
                               __LINE__, 
                               __METHOD__, 
                               __FILE__, 
                               $token);

                        $bytes = 8;

                    break;

                }

            break;
            case 'float':
            case 'double':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * CRNRSTN :: PHP Support.
                 * PHP 5 >= 5.5, PHP 7, PHP 8.
                 *
                 */
                $bytes = $this->tidy_boolean(self::$R_data['mbstring_func_overload']) ? \mb_strlen((string) $data, '8bit') : \strlen((string) $data);

            break;
            case 'array':
            case 'object':
            case 'resource':
            case 'resource (closed)':
            case 'unknown type':

                $bytes = \strlen(\serialize($data));

            break;
            case 'null':

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * SOURCE :: https://stackoverflow.com/questions/2430655/java-does-null-variable-require-space-in-memory
                 * COMMENT :: https://stackoverflow.com/a/2430672
                 * AUTHOR :: dsimcha :: https://stackoverflow.com/users/23903/dsimcha
                 *
                 * In Java, null is just a 
                 * value that a reference (which is 
                 * basically a restricted pointer) 
                 * can have. It means that 
                 * the reference refers to 
                 * nothing. In this case you still 
                 * consume the space for the 
                 * reference. This is 4 bytes on 
                 * 32-bit systems or 8 bytes on 
                 * 64-bit systems. However, 
                 * you're not consuming any space 
                 * for the class that the 
                 * reference points to until you 
                 * actually allocate an 
                 * instance of that class to 
                 * point the reference at. 
                 *
                 */

                switch(self::$R_data['os_bit_size']){
                    case 32:

                        $bytes = 4;

                    break;
                    case 64:

                        $bytes = 8;

                    break;
                    default:

                        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                         * HOOOSTON, VE HAFF PROBLEM!
                         * https://www.wired.com/2011/04/alt-text-spacecraft/
                         *
                         */
                        $clr_ssl_msg = 'Unknown operating ' . 
                                       'system bit size. 8 bytes will ' . 
                                       'be assigned for NULL data; on ' . 
                                       '64-bit platforms, CRNRSTN :: ' . 
                                       'reports NULL data as 8 bytes.';
                        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
                        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                        $token = array(
                                 'token'                   => $msg_token, 
                                 'token_generation_date'   => $token_generation_date, 
                                 'request_type'            => __METHOD__, 
                                 'code'                    => 200, 
                                 'clr_ssl_msg'             => $clr_ssl_msg);
                        $this->error_log(
                               $clr_ssl_msg, 
                               \LOG_NOTICE, 
                               \E_NOTICE, 
                               __LINE__, 
                               __METHOD__, 
                               __FILE__, 
                               $token);

                        $bytes = 8;

                    break;

                }

            break;

        }

        return $bytes;

    }

